import * as THREE from "three";
import { useFBO } from "@threlte/extras";
export function useDoubleFBO(width, height, options) {
    const read = useFBO({
        size: {
            width,
            height,
        },
        ...options
    });
    const write = useFBO({
        size: {
            width,
            height,
        },
        ...options
    });
    const fbo = $state({
        read,
        write,
        swap: () => {
            const temp = fbo.read;
            fbo.read = fbo.write;
            fbo.write = temp;
        },
        dispose: () => {
            read.dispose();
            write.dispose();
        },
    });
    return fbo;
}
;
